// === NODO 2: CONSTRUIR PROMPT PARA GEMINI ===
const d = $input.first().json.body || $input.first().json;
const s = d.iso_38500_scores;

// Mapa de dimensiones con contexto rico
const dims = [
  { key: 'responsabilidad', name: 'Gobernanza Ciberseguridad (CISO)', score: s.responsabilidad, context: 'Existencia de un CISO formal y SOC activo para proteger datos médicos del Hemocentro contra Ransomware' },
  { key: 'conformidad', name: 'Protección de Datos (Ley 1581)', score: s.conformidad, context: 'Auditoría y protección de datos de pacientes y donantes, riesgo de multas SIC de hasta 2000 SMMLV' },
  { key: 'servidores', name: 'Infraestructura Servidores Hemocentro', score: s.servidores, context: 'Estado de servidores físicos que hospedan HeVa (base datos sangre). Fallo paraliza $771M COP en ingresos' },
  { key: 'backups', name: 'Continuidad de Negocio (DRP/Backups)', score: s.backups, context: 'Respaldos inmutables en nube y simulacros DRP semestrales. RTO objetivo < 4 horas' },
  { key: 'interoperabilidad', name: 'Integración API Gateway HL7/FHIR', score: s.interoperabilidad, context: 'Integración de HeVa, Siesa y Q-Symphony con estándar hospitalario HL7/FHIR' },
  { key: 'canales_donantes', name: 'Canales Digitales Donantes (App Móvil)', score: s.canales_donantes, context: 'App móvil propia y agendamiento online para donantes de sangre de la seccional' },
  { key: 'portal_educativo', name: 'Portal Educativo Instituto (PSE)', score: s.portal_educativo, context: 'Portal transaccional con matrícula en línea y pasarela PSE integrada a Siesa, protege $61M ingresos Instituto' },
  { key: 'apropiacion_digital', name: 'Apropiación Digital Voluntariado', score: s.apropiacion_digital, context: 'Capacitación de médicos, enfermeros y voluntarios en herramientas corporativas y ciberseguridad' },
  { key: 'mesa_ayuda', name: 'Mesa de Ayuda TI (SLA)', score: s.mesa_ayuda, context: 'Mesa de ayuda formal con asignación automática de incidencias y SLAs medibles para personal clínico' },
  { key: 'convenios_makaia', name: 'Convenio Makaia (Microsoft 365)', score: s.convenios_makaia, context: 'Gestión del convenio sin fines de lucro con Makaia para licenciamiento de Microsoft 365 del personal Valle' }
];

const avg = parseFloat(d.computed_maturity);
const status = d.conformance_status;

// Construir la lista de dimensiones para el prompt
const dimList = dims.map(dm => `  - ${dm.name}: ${dm.score}/5 (Contexto: ${dm.context})`).join('\n');

// Prompt rico y estructurado para Gemini
const prompt = `Eres un consultor senior de Gobierno de TI e ISO 38500 especializado en entidades sin ánimo de lucro del sector salud en Colombia.

Analiza el siguiente autodiagnóstico de madurez de TI de la Cruz Roja Colombiana - Seccional Valle del Cauca (PETI 2026-2030):

PUNTUACIÓN GLOBAL: ${avg}/5.0 — Estado: ${status}

DIMENSIONES EVALUADAS (escala 0-5):
${dimList}

Genera un análisis ejecutivo COMPLETO y estructurado en el siguiente formato JSON exacto (no agregues texto fuera del JSON):

{
  "resumen_ejecutivo": "Párrafo de 3-4 oraciones describiendo el estado general de la organización, los riesgos más críticos y el potencial de mejora. Sé específico sobre el Hemocentro y los $771M COP en riesgo.",
  "nivel_riesgo_global": "CRÍTICO | MODERADO | ÓPTIMO",
  "color_riesgo": "red | amber | green",
  "puntos_fuertes": [
    "Fortaleza específica 1 basada en los scores altos",
    "Fortaleza específica 2"
  ],
  "brechas_criticas": [
    {
      "dimension": "Nombre de la dimensión con score más bajo",
      "score": 0,
      "impacto_negocio": "Impacto concreto en pesos COP o en operaciones clínicas",
      "accion_inmediata": "Acción específica y ejecutable en los próximos 90 días"
    }
  ],
  "plan_priorizado": [
    {
      "prioridad": 1,
      "proyecto": "Nombre del proyecto PETI",
      "inversion_estimada": "$XXM COP",
      "roi_esperado": "Retorno esperado en 12 meses",
      "plazo": "30 días | 90 días | 6 meses | 1 año"
    }
  ],
  "indicadores_clave": [
    {
      "kpi": "Nombre del KPI",
      "valor_actual": "Valor basado en el score dado",
      "meta_2030": "Valor objetivo",
      "tendencia": "↑ subiendo | ↓ bajando | → estable"
    }
  ],
  "mensaje_junta_directiva": "Mensaje ejecutivo de 2 oraciones para presentar a la junta directiva de la seccional, explicando el impacto humanitario de estas brechas de TI.",
  "siguiente_paso_inmediato": "Una sola acción concreta y urgente que debe ejecutarse esta semana."
}`;

return [{ json: { prompt, scores: d.iso_38500_scores, avg, status, email: d.email, original_payload: d } }];
